import numpy as np
from PIL import Image
im = Image.open('radiograph.jpg').convert('L')
a = np.asarray(im, dtype=np.float32)

def patch_mean(x, y, s=14):
    return a[y-s:y+s, x-s:x+s].mean()

# Sample grid over upper molar regions (both sides), step 30 px
print("Upper molar region means (x from 620 to 900 and 1600 to 1880, y 380..560):")
for y in range(380, 561, 30):
    row = []
    for x in list(range(620, 901, 40)) + list(range(1600, 1881, 40)):
        row.append(f"{x}:{patch_mean(x,y):.0f}")
    print(y, ' | '.join(row))
print()
print("Lower molar/premolar region means (y 720..880):")
for y in range(700, 881, 30):
    row = []
    for x in list(range(600, 881, 40)) + list(range(1400, 1781, 40)):
        row.append(f"{x}:{patch_mean(x,y):.0f}")
